SEC = [
 (92, 'చదవండి – ఆలోచించి చెప్పండి (పుట 84)', [
  '1) శ్రీశ్రీ గేయంలో కర్షక వీరులు (రైతులు), కార్మిక వీరులు (కూలీలు, శ్రామికులు) గురించి ప్రస్తావించారు.',
  '2) వారి శ్రమ, చెమట అమూల్యమైనవి – ఏ ధనంతోనూ వాటి విలువ కట్టలేం; అందుకే వారి శ్రమకు ఖరీదు లేదు, ఖరీదు కట్టే షరాబు (వ్యాపారి) లేడన్నారు.',
  '3) ఘర్మజలం కాలువలు కట్టడం = చెమట ఎంతో ఎక్కువగా కారి కాలువల్లా ప్రవహించడం – అంటే చాలా కష్టపడి పనిచేయడం.']),
 (96, 'అవగాహన – ప్రతిస్పందన అ, ఆ (పుట 88)', [
  'అ-1) పద్యాలను రాగయుక్తంగా పాడండి.',
  'అ-2) నచ్చిన పద్యం: “వాని రెక్కల కష్టంబు లేనినాడు …” (పద్యం 4) – ప్రపంచానికి అన్నం పెట్టే శ్రమజీవికే తిండి లేదనే చేదు నిజాన్ని హృదయానికి హత్తుకునేలా చెప్పింది.',
  'ఆ) 1. ఎ) 1862 సెప్టెంబర్ 21 2. ఎ) వెంకట రామదాసు, కౌసల్యమ్మ 3. బి) కన్యాశుల్కము 4. ఎ) గిడుగు వెంకట రామమూర్తి.']),
 (97, 'అవగాహన ఇ; వ్యక్తీకరణ (పుట 89)', [
  'ఇ-1) “కృపారహితాత్ములు” = దయలేని మనసు గలవారు (కృప = దయ, రహిత = లేని, ఆత్మ = మనసు).',
  'అ-1 జాషువ, అ-2 ఖండకావ్యం, అ-3 నేపథ్యం, అ-4 భరతావని ఋణం; ఆ-1 సారాంశం, ఆ-4 వ్యాసం – పాఠ ప్రశ్నల జవాబులు చూడండి.',
  'ఆ-2) కవి ఆవేదన: 1) శ్రమజీవి అమాయకుడు, తృప్తిపరుడు, నీతిమంతుడు. 2) అయినా ఆకలితో కాలిపోతున్నాడు. 3) తనను దోచినవారికే చెప్పులు కుట్టి సేవ చేస్తున్నాడు. 4) అతని శ్రమతోనే పంటలు పండుతాయి. 5) కానీ అతనికే అన్నం లేదు, గంజే గతి. 6) జంతువులకు పాలు, పంచదార పెట్టే సమాజం మనిషిని దూరం పెడుతోంది. 7) తన బాధ చెప్పుకోవడానికి గబ్బిలమే దిక్కైంది. 8) ఈ అన్యాయాలపై కవి ఆవేదన న్యాయమైనది – సమాజం మారాలి.',
  'ఆ-3) మా ప్రాంత శ్రామికులు: 1) రైతులు – ఉదయం నుండి పొలాల్లో వరి, నిమ్మ సాగు. 2) వ్యవసాయ కూలీలు – నాట్లు, కోతలు. 3) మత్స్యకారులు – తీరంలో సముద్రంలో చేపల వేట. 4) ఉప్పు మడుల కార్మికులు. 5) భవన నిర్మాణ కూలీలు. 6) వీరు రోజు కూలీతోనే జీవిస్తారు. 7) పిల్లల చదువు, ఆరోగ్యం కోసం కష్టపడతారు. 8) వర్షాలు, తుఫానులు వచ్చినప్పుడు వీరి జీవనం కష్టమవుతుంది.',
  'పదజాలం అ-1) చిక్కిన = దొరికిన – నాకు దొరికిన పుస్తకాన్ని యజమానికి ఇచ్చాను.']),
 (98, 'పదజాలం అ, ఆ, ఇ, ఈ (పుట 90)', [
  'అ-2) క్షుద్బాధ = ఆకలి బాధ – అన్నదానంతో పేదల ఆకలిబాధ తీర్చాలి. 3) భుక్తి = తిండి – కష్టపడితే భుక్తికి లోటు ఉండదు. 4) బీదవాడు = పేదవాడు – పేదవారికి సహాయం చేయాలి.',
  'ఆ) పర్యాయపదాలు: 1. నృపాలకుడు = రాజు, భూపాలుడు 2. శివుడు = శంకరుడు, ఈశ్వరుడు, పినాకపాణి 3. మనుజుడు = మనిషి, మానవుడు 4. మేను = శరీరం, దేహం.',
  'ఇ) నానార్థాలు: 1. దిక్కు = దిశ, శరణం 2. శిరస్సు = తల, శిఖరం (కొన) 3. పాదం = కాలు, పద్యంలో నాలుగో భాగం 4. మృగం = జంతువు, జింక.',
  'ఈ) ప్రకృతి – వికృతి: ఉదా: అరుంధతి – ఆరంజోతి; 1. మనుష్యుడు – మనిషి 2. కులం – కొలము 3. ధర్మం – దమ్మం 4. పట్టణం – పత్తనం.']),
 (99, 'పదజాలం ఉ – పద్యభావం (పుట 91)', [
  'క్రమసంఖ్యల ఆధారంగా పద్యం 4 భావం: అతని (కష్టజీవి) యొక్క రెక్కల కష్టం లేకుండాపోయిన రోజున పంటలు పండుటకు, ఆనందించుటకు (పులకించుటకు) అనుమానించును. అతడు స్వేదమును (చెమటను) చిందించి ప్రజలకు అన్నం పెడతాడు; అతనికి మాత్రం తిండి లేకుండాపోయింది. (పుస్తకంలోని సంఖ్యల క్రమంలో పదాలు పేర్చి రాయండి.)']),
 (101, 'వ్యాకరణ అభ్యాసం 1, 2 (పుట 93)', [
  'అభ్యాసం 1: 1. భరతోర్వరకు = భరత + ఉర్వరకు (అ + ఉ = ఓ) – గుణ సంధి 2. వీడున్న = వీడు + ఉన్న – ఉత్వ సంధి 3. సుతుండొక్కడు = సుతుండు + ఒక్కడు – ఉత్వ సంధి 4. ఔనౌను = ఔను + ఔను – ఆమ్రేడిత సంధి 5. ఏమని = ఏమి + అని – ఇత్వ సంధి 6. విషాదాశ్రువులు = విషాద + అశ్రువులు (అ + అ = ఆ) – సవర్ణదీర్ఘ సంధి 7. మహోన్నత = మహా + ఉన్నత (ఆ + ఉ = ఓ) – గుణ సంధి 8. అమాయకుడెల్ల = అమాయకుడు + ఎల్ల – ఉత్వ సంధి 9. ఉన్నదని = ఉన్నది + అని – ఇత్వ సంధి 10. ముద్దవోలె = ముద్ద + పోలె (ప → వ) – గసడదవాదేశ సంధి.',
  'అభ్యాసం 2: 1. అరుంధతీ సుతుండు – అరుంధతి యొక్క సుతుడు – షష్ఠీ తత్పురుష 2. భరత వీరుడు – భరతదేశము యొక్క వీరుడు – షష్ఠీ తత్పురుష 3. పాపకారణము – పాపము యొక్క కారణము – షష్ఠీ తత్పురుష 4. జన్మహక్కు – జన్మము చేత (వలన) వచ్చిన హక్కు – తృతీయా తత్పురుష']),
 (102, 'వ్యాకరణ అభ్యాసం 2 (5–10); ప్రాజెక్టు (పుట 94)', [
  '5. విచిత్రధర్మము – విచిత్రమైన ధర్మము – విశేషణ పూర్వపద కర్మధారయ 6. క్రొత్తయూహ – క్రొత్తదైన ఊహ – విశేషణ పూర్వపద కర్మధారయ 7. ఊహాంకురము – ఊహ అనెడి అంకురము – అవధారణ పూర్వపద కర్మధారయ (రూపక సమాసం) 8. గాలివెలుతురు – గాలియు, వెలుతురును – ద్వంద్వ సమాసం 9. నలుదిక్కులు – నాలుగు సంఖ్య గల దిక్కులు – ద్విగు సమాసం 10. సస్యరమ – సస్యము అనెడి రమ (లక్ష్మి) – అవధారణ పూర్వపద కర్మధారయ.',
  'ప్రాజెక్టు: వృత్తి – పనిముట్లు: రైతు – నాగలి, కొడవలి, పార; కుమ్మరి – సారె, ఆవం; కమ్మరి – కొలిమి, సుత్తి, దాగలి; వడ్రంగి – ఉలి, బాడిస, రంపం; చేనేత – మగ్గం, కండె; చర్మకారుడు – ఆరె, సూది, దారం (బొమ్మలతో రాయండి).']),
]
